List<IndiaSubDistrict> subDistrictsForDistrict(String districtCode) =>
    indiaSubDistricts
        .where((item) => item.districtCode == districtCode)
        .toList(growable: false);

List<IndiaSubDistrict> subDistrictsForState(String stateCode) =>
    indiaSubDistricts
        .where((item) => item.stateCode == stateCode)
        .toList(growable: false);

IndiaSubDistrict? findSubDistrictByCode(String code) {
  for (final item in indiaSubDistricts) {
    if (item.code == code) return item;
  }
  return null;
}

List<IndiaSubDistrict> searchSubDistricts(String query) {
  final normalized = query.trim().toLowerCase();
  if (normalized.isEmpty) return const <IndiaSubDistrict>[];
  return indiaSubDistricts.where((item) =>
    item.name.toLowerCase().contains(normalized) ||
    item.localName.toLowerCase().contains(normalized) ||
    item.districtName.toLowerCase().contains(normalized) ||
    item.stateName.toLowerCase().contains(normalized)
  ).toList(growable: false);
}
